import type { PersonInput } from "@/lib/schema";

/**
 * Heroes and heroines: donors and philanthropists. The people who paid for cancer research and care, or raised
 * the money for it: founding gifts behind institutes and cancer centres, foundations that back early ideas, and
 * fundraisers who turned a diagnosis into a research fund. Shown in the "Donors and philanthropists" group of
 * /heroes/ (src/app/heroes/page.tsx) and as the "Donors" chip on /people/.
 *
 * Rules for this file:
 *  - Every record carries the tags "hero" and "donor" (first role tag after "hero" decides the group), plus
 *    "patient" where the donor's own illness is part of the public record.
 *  - Gift facts (amounts, years, recipients) appear ONLY where a primary source states them: the recipient's own
 *    announcement or history page, the donor's foundation, the Giving Pledge, or the Chronicle of Philanthropy.
 *    Where only news coverage gives a figure, the figure is left out and the record says what was built instead.
 *  - `links` point at those primary sources. `wikipedia` is set only where the English article exists (checked
 *    against the Wikipedia REST summary API on the asOf date).
 *  - Recipient institutions are linked by id so that /heroes/ can derive "What the gifts built" from the graph.
 *    Foundations without a record elsewhere live in src/data/institutions/donor-foundations.ts.
 *  - People already on /heroes/ who also gave or raised money (Terry Fox, Evelyn Lauder, Mary Lasker, Jim Valvano,
 *    Alex Scott, Deborah James, Stephen Sutton, Katie Couric, Einar Gustafson) are linked from here, not duplicated.
 */
const asOf = "2026-09-10";
type P = Omit<PersonInput, "kind" | "asOf">;
const p = (x: P): PersonInput => ({ kind: "person", asOf, links: x.profiles, ...x });
const W = (slug: string) => `https://en.wikipedia.org/wiki/${slug}`;
const src = (label: string, url: string) => ({ label, url });

